import Foundation
import XCTest
@testable import MacropadCore

/// Fixtures were generated by the Python `macropad` CLI (vibe-coder-keyboard), so these tests
/// prove the Swift port sends exactly the same bytes and accepts the same syntax.
final class GoldenTests: XCTestCase {
    struct Golden: Decodable {
        struct Bind: Decodable {
            let action: String?
            let canonical: String?
            let slot: String
            let layer: Int
            let packets: [String]
        }
        let bind: [Bind]
        let invalid: [String]
        let led: [String: [String]]
    }

    struct ApplyFixture: Decodable {
        let yaml: String
        let packets: [String]
    }

    func fixture<T: Decodable>(_ name: String) throws -> T {
        let url = try XCTUnwrap(Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "Fixtures"))
        return try JSONDecoder().decode(T.self, from: Data(contentsOf: url))
    }

    /// The CLI prints packets as hex with trailing zero bytes trimmed.
    func hex(_ packets: [[UInt8]]) -> [String] {
        packets.map { packet in
            var bytes = packet
            while bytes.count > 1, bytes.last == 0 { bytes.removeLast() }
            return bytes.map { String(format: "%02x", $0) }.joined()
        }
    }

    func testBindPacketsMatchCLI() throws {
        let golden: Golden = try fixture("golden")
        XCTAssertGreaterThan(golden.bind.count, 100)
        for item in golden.bind {
            let slot = try XCTUnwrap(Slot(rawValue: item.slot))
            let action = try item.action.map { try Action(parsing: $0) }
            XCTAssertEqual(action?.canonical, item.canonical, "canonical of \(item.action ?? "nil")")
            XCTAssertEqual(hex(PadProtocol.bindPackets(slot: slot, layer: item.layer, action: action)), item.packets,
                           "\(item.action ?? "clear") on \(item.slot) layer \(item.layer)")
        }
    }

    func testAllPacketsAre64Bytes() throws {
        let action = try Action(parsing: "h, e, l, l, o")
        for packet in PadProtocol.bindPackets(slot: .knobRight, layer: 3, action: action) {
            XCTAssertEqual(packet.count, 64)
            XCTAssertEqual(packet.first, 0x03)
        }
    }

    func testInvalidActionsRejected() throws {
        let golden: Golden = try fixture("golden")
        for text in golden.invalid {
            XCTAssertThrowsError(try Action(parsing: text), "should reject “\(text)”")
        }
    }

    func testLEDPacketsMatchCLI() throws {
        let golden: Golden = try fixture("golden")
        for mode in PadProtocol.ledModes {
            XCTAssertEqual(hex(PadProtocol.ledPackets(mode: mode)), golden.led[String(mode)])
        }
    }

    func testApplyMatchesCLI() throws {
        let fixture: ApplyFixture = try fixture("apply")
        let layout = try Layout.parse(yaml: fixture.yaml)
        XCTAssertEqual(layout.led, 2)
        XCTAssertEqual(hex(try PadProtocol.applyPackets(layout)), fixture.packets)
    }

    func testBuiltInPresetsAreValid() throws {
        for preset in Preset.builtIns {
            _ = try PadProtocol.applyPackets(preset.layout)
        }
        let fixture: ApplyFixture = try fixture("apply")
        var vibe = try Layout.parse(yaml: fixture.yaml)
        vibe.led = nil
        XCTAssertEqual(Preset.vibeCoder.layout, vibe, "built-in Vibe Coder preset should match the repo's YAML")
    }
}

final class LayoutTests: XCTestCase {
    func testRoundTrip() throws {
        var layout = Layout(led: 1)
        try layout.set(layer: 1, slot: .key1, actionText: "CMD + C")
        try layout.set(layer: 1, slot: .key4, actionText: "cmd+a, cmd+c")
        try layout.set(layer: 1, slot: .key5, actionText: "1")
        try layout.set(layer: 2, slot: .knobRight, actionText: "volume-up")
        XCTAssertEqual(layout.text(layer: 1, slot: .key1), "cmd+c")
        let yaml = layout.yaml
        XCTAssertEqual(yaml, """
        led: 1
        layers:
          1:
            key1: cmd+c
            key4: cmd+a, cmd+c
            key5: '1'
          2:
            knob-right: volume-up

        """)
        XCTAssertEqual(try Layout.parse(yaml: yaml), layout)
    }

    func testClearRemovesEmptyLayers() throws {
        var layout = Layout()
        try layout.set(layer: 2, slot: .key1, actionText: "a")
        layout.clear(layer: 2, slot: .key1)
        XCTAssertTrue(layout.layers.isEmpty)
        XCTAssertEqual(layout.yaml, "layers: {}\n")
    }

    func testRejectsBadFiles() {
        XCTAssertThrowsError(try Layout.parse(yaml: "led: 7\n"))
        XCTAssertThrowsError(try Layout.parse(yaml: "layers:\n  4:\n    key1: a\n"))
        XCTAssertThrowsError(try Layout.parse(yaml: "layers:\n  1:\n    key9: a\n"))
        XCTAssertThrowsError(try Layout.parse(yaml: "layers:\n  1:\n    key1: cmd+delete\n"))
        XCTAssertThrowsError(try Layout.parse(yaml: "colors: 1\n"))
        XCTAssertEqual(try Layout.parse(yaml: ""), Layout())
    }

    func testMissingFileIsEmpty() throws {
        let url = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString + ".yaml")
        XCTAssertEqual(try Layout.load(from: url), Layout())
    }

    func testPresetStore() throws {
        let dir = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString)
        let store = PresetStore(directory: dir)
        try store.save(Preset.media.layout, named: "Meu preset")
        let presets = store.userPresets()
        XCTAssertEqual(presets.map(\.name), ["Meu preset"])
        XCTAssertEqual(presets.first?.layout, Preset.media.layout)
        try store.delete(presets[0])
        XCTAssertTrue(store.userPresets().isEmpty)
    }
}

final class DisplayTests: XCTestCase {
    override func setUp() { L10n.override = .pt }
    override func tearDown() { L10n.override = nil }

    func testLabels() throws {
        XCTAssertEqual(try Action(parsing: "shift+cmd+4").displayLabel, "⇧⌘4")
        XCTAssertEqual(try Action(parsing: "opt+p, left").displayLabel, "⌥P ←")
        XCTAssertEqual(try Action(parsing: "volume-up").displayLabel, "Vol +")
        XCTAssertEqual(try Action(parsing: "ctrl+scroll-down").displayLabel, "⌃Rolar ↓")
        XCTAssertEqual(try Action(parsing: "f13").displayLabel, "F13")
        XCTAssertEqual(Action.empty.displayLabel, "")
    }

    func testMacKeyCodesMapToKnownKeys() throws {
        for (code, name) in MacKeyCodes.names {
            XCTAssertNoThrow(try Action(parsing: name), "keycode 0x\(String(code, radix: 16)) -> \(name)")
        }
        XCTAssertEqual(MacKeyCodes.names[0x15], "4")
    }

    func testSuggestions() {
        do {
            _ = try Action(parsing: "volme-up")
            XCTFail("should throw")
        } catch let error as ActionError {
            XCTAssertTrue(error.suggestions.contains("volume-up"), "\(error.suggestions)")
        } catch {
            XCTFail("\(error)")
        }
    }
}

final class AppConfigTests: XCTestCase {
    func testTriggersAreValidUniqueHyperCombos() throws {
        XCTAssertEqual(Set(AppConfig.triggerPool).count, 36)
        for trigger in AppConfig.triggerPool {
            let action = try Action(parsing: trigger)
            XCTAssertEqual(action.canonical, trigger, "trigger must already be canonical")
            guard case .keys(let steps) = action else { return XCTFail() }
            XCTAssertEqual(steps.count, 1)
            XCTAssertEqual(steps[0].mods, 0x0F)
            XCTAssertNotNil(MacKeyCodes.names.first { $0.value == Keys.keyName(for: steps[0].code) },
                            "\(trigger) needs a macOS key code for the global hot key")
        }
    }

    func testAllocateLookupAndPrune() throws {
        var config = AppConfig()
        let first = try XCTUnwrap(config.freeTrigger())
        XCTAssertEqual(first, "ctrl+opt+shift+cmd+1")
        config.commands[first] = Command(kind: .openApp, value: "/Applications/Safari.app")
        XCTAssertEqual(config.freeTrigger(), "ctrl+opt+shift+cmd+2")
        XCTAssertEqual(config.freeTrigger(reserved: ["ctrl+opt+shift+cmd+2"]), "ctrl+opt+shift+cmd+3")

        // Spelling in the layout file doesn't matter.
        XCTAssertEqual(config.command(forActionText: "cmd+shift+opt+ctrl+1")?.label, "Safari")
        XCTAssertNil(config.command(forActionText: "cmd+c"))

        var layout = Layout()
        try layout.set(layer: 1, slot: .key3, actionText: first)
        config.commands["ctrl+opt+shift+cmd+9"] = Command(kind: .shell, value: "say oi")
        config.pruneCommands(keeping: [layout])
        XCTAssertEqual(Array(config.commands.keys), [first])
    }

    func testRulesAndRoundTrip() throws {
        var config = AppConfig()
        config.autoSwitch = true
        config.setRule(AutoRule(bundleID: "com.apple.Terminal", appName: "Terminal", preset: Preset.vibeCoder.id))
        config.setRule(AutoRule(bundleID: "com.apple.Terminal", appName: "Terminal", preset: Preset.editing.id))
        XCTAssertEqual(config.rules.count, 1)
        XCTAssertEqual(config.presetID(for: "com.apple.Terminal"), Preset.editing.id)
        XCTAssertNil(config.presetID(for: "com.spotify.client"))
        config.defaultPreset = Preset.media.id
        XCTAssertEqual(config.presetID(for: "com.spotify.client"), Preset.media.id)
        config.commands["ctrl+opt+shift+cmd+a"] = Command(kind: .openURL, value: "https://claude.ai")

        let url = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString + ".json")
        try config.save(to: url)
        XCTAssertEqual(AppConfig.load(from: url), config)
        XCTAssertEqual(AppConfig.load(from: url.appendingPathExtension("missing")), AppConfig())
    }

    func testCommandValidityAndLabels() {
        XCTAssertFalse(Command(kind: .openApp, value: "  ").isValid)
        XCTAssertFalse(Command(kind: .openURL, value: "not a url").isValid)
        XCTAssertTrue(Command(kind: .openURL, value: "https://github.com/x").isValid)
        XCTAssertEqual(Command(kind: .openURL, value: "https://github.com/x").label, "github.com")
        XCTAssertEqual(Command(kind: .shortcut, value: "Modo foco").label, "Modo foco")
    }
}

final class L10nTests: XCTestCase {
    override func tearDown() { L10n.override = nil }

    func testTranslateAndFill() {
        XCTAssertEqual(L10n.translate("Tecla %@", .pt, ["3"]), "Tecla 3")
        XCTAssertEqual(L10n.translate("Tecla %@", .en, ["3"]), "Key 3")
        XCTAssertEqual(L10n.translate("Tecla %@", .es, ["3"]), "Tecla 3")
        XCTAssertEqual(L10n.translate("Gravar no pad", .en, []), "Write to pad")
        XCTAssertEqual(L10n.translate("texto sem tradução", .en, []), "texto sem tradução")
        // Arguments with % can't break formatting.
        XCTAssertEqual(L10n.translate("Em uso: %@", .en, ["100%@ %d"]), "In use: 100%@ %d")
        XCTAssertEqual(L10n.translate("%@ abre “%@” (envia %@)", .es, ["Tecla 1", "Safari", "⌘1"]),
                       "Tecla 1 abre “Safari” (envía ⌘1)")
    }

    func testOverrideSwitchesEverything() {
        L10n.override = .en
        XCTAssertEqual(Slot.knobPress.title, "Knob press")
        XCTAssertEqual(Preset.media.displayName, "Media")
        XCTAssertEqual(try Action(parsing: "volume-up").displayLabel, "Vol +")
        XCTAssertThrowsError(try Action(parsing: "")) { XCTAssertEqual($0.localizedDescription, "The action is empty") }
        L10n.override = .es
        XCTAssertEqual(Action.mouseTitle("right-click"), "Clic derecho")
        XCTAssertEqual(Preset.media.id, "builtin:Mídia", "ids must not depend on the language")
    }

    func testTablesHaveTheSameKeys() {
        XCTAssertEqual(L10n.keys.en, L10n.keys.es)
    }

    func testConfigKeepsLanguageAndOldFilesLoad() throws {
        var config = AppConfig()
        config.language = .es
        let url = FileManager.default.temporaryDirectory.appendingPathComponent(UUID().uuidString + ".json")
        try config.save(to: url)
        XCTAssertEqual(AppConfig.load(from: url).language, .es)
        // A file from an older version (no "language", no "rules") still loads.
        try Data(#"{"autoSwitch": true, "commands": {}}"#.utf8).write(to: url)
        let old = AppConfig.load(from: url)
        XCTAssertTrue(old.autoSwitch)
        XCTAssertNil(old.language)
    }
}
